declare(strict_types=1);$base=rtrim(str_replace('\\','/',dirname($_SERVER['SCRIPT_NAME']??'/player/universe-create.php')),'/');if(session_status()!==PHP_SESSION_ACTIVE){$secure=(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off');session_set_cookie_params(['httponly'=>true,'secure'=>$secure,'samesite'=>'Lax','path'=>'/']);session_start();}if(empty($_SESSION['core_user']['id'])){header('Location: '.$base.'/account.php');exit;}$root=dirname(__DIR__);define('CORE_ROOT',$root);require $root.'/bootstrap.php';$cfg=require $root.'/config/app.php';$store=new \Core\Storage\JsonStorage((string)$cfg['storage']['path']);$cid=(string)($_GET['character_id']??'');$character=$cid!==''?$store->read('characters',$cid):null;if(!$character||($character['owner_account_id']??null)!==(string)$_SESSION['core_user']['id']){http_response_code(404);exit('Character not found for this account.');}$releaseVersion=require $root.'/config/version.php';function h($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Create Universe · CORE</title><link rel="stylesheet" href="<?=$base?>/player.css"><script src="https://cdn.babylonjs.com/babylon.js"></script></head><body><header class="topbar"><a class="brand" href="<?=$base?>/selection.php"><span class="brand-mark">C</span><span>CORE <small>UNIVERSE CREATION</small></span></a><span class="build-tag"><?=h($releaseVersion)?></span></header><main class="player-flow"><section class="panel"><div class="eyebrow">STEP 2 · UNIVERSE CONFIGURATION</div><h1>Give <?=h($character['name'])?> a <span>frontier.</span></h1><p>Choose a seed and tune generation characteristics. The seed and settings together define this universe. Preview updates as you change the controls.</p><div class="universe-create-layout"><div class="universe-settings"><form method="post" action="<?=$base?>/player-action.php" class="creation-form" id="universeCreateForm"><input type="hidden" name="csrf" value="<?=h($_SESSION['core_csrf']??=bin2hex(random_bytes(32)))?>"><input type="hidden" name="action" value="create_universe"><input type="hidden" name="character_id" value="<?=h($cid)?>"><label for="universeSeed">Universe seed</label><input id="universeSeed" name="seed" required maxlength="120" minlength="3" placeholder="e.g. The Far Lantern" autocomplete="off"><div class="universe-slider"><label for="system_density">System density <output id="system_density_out">50</output></label><input id="system_density" name="system_density" type="range" min="0" max="100" value="50"><small>Controls how many star systems are generated.</small></div><div class="universe-slider"><label for="anomaly_rate">Anomaly rate <output id="anomaly_rate_out">25</output></label><input id="anomaly_rate" name="anomaly_rate" type="range" min="0" max="100" value="25"><small>Higher values produce more anomalous systems.</small></div><div class="universe-slider"><label for="binary_star_rate">Binary star frequency <output id="binary_star_rate_out">30</output></label><input id="binary_star_rate" name="binary_star_rate" type="range" min="0" max="100" value="30"><small>Influences the share of binary systems.</small></div><div class="universe-slider"><label for="nebula_presence">Nebula presence <output id="nebula_presence_out">35</output></label><input id="nebula_presence" name="nebula_presence" type="range" min="0" max="100" value="35"><small>Influences nebula-adjacent system frequency.</small></div><div class="universe-summary"><strong>Preview characteristics</strong><dl class="stats"><div><dt>Seed fingerprint</dt><dd id="previewFingerprint">Enter a seed</dd></div><div><dt>Estimated star systems</dt><dd id="previewSystemCount">—</dd></div><div><dt>Anomaly setting</dt><dd id="previewAnomaly">25%</dd></div></dl><p id="previewStatus" class="fine-print" aria-live="polite">Enter a seed to generate a preview.</p></div><div class="creation-actions"><a class="button-secondary" href="<?=$base?>/selection.php">Back to characters</a><button type="submit">Create and assign universe</button></div></form></div><div class="universe-preview-panel"><div class="eyebrow">BABYLON.JS · LIVE PREVIEW</div><h2>Universe visualization</h2><div class="universe-preview-canvas-wrap"><canvas id="universePreviewCanvas" aria-label="Interactive 3D universe preview"></canvas><div id="universePreviewFallback" class="preview-status">Loading 3D preview…</div></div><div class="map-footer"><span id="universePreviewMapStatus">Waiting for seed</span><span>Drag to orbit · Scroll to zoom</span></div></div></div></section></main><script>
(() => {
 const $=id=>document.getElementById(id), keys=['system_density','anomaly_rate','binary_star_rate','nebula_presence'];
 const apiBase=<?=json_encode(rtrim(dirname($base),'/'))?>; let engine=null,scene=null,meshes=[]; let requestSeq=0;
 function settings(){const o={};keys.forEach(k=>o[k]=Number($(k).value));return o;}
 function displayControls(){keys.forEach(k=>$(k+'_out').textContent=$(k).value);$('previewAnomaly').textContent=$('anomaly_rate').value+'%';}
 function render(universe){if(!window.BABYLON){$('universePreviewFallback').style.display='block';$('universePreviewFallback').textContent='Babylon.js unavailable; the generation form remains usable.';return;}
  try {if(!engine){engine=new BABYLON.Engine($('universePreviewCanvas'),true,{adaptToDeviceRatio:true});scene=new BABYLON.Scene(engine);scene.clearColor=new BABYLON.Color4(.02,.035,.06,1);const cam=new BABYLON.ArcRotateCamera('universe-preview-camera',-Math.PI/2,Math.PI/3,32,BABYLON.Vector3.Zero(),scene);cam.attachControl($('universePreviewCanvas'),true);cam.lowerRadiusLimit=8;cam.upperRadiusLimit=90;new BABYLON.HemisphericLight('preview-light',new BABYLON.Vector3(0,1,0),scene).intensity=.9;engine.runRenderLoop(()=>scene.render());window.addEventListener('resize',()=>engine.resize());}
   meshes.forEach(m=>m.dispose());meshes=[];const systems=universe?.systems||[];systems.forEach((sys,i)=>{const x=(Number(sys.x)||0)/650,y=((i%4)-1.5)*.9,z=(Number(sys.y)||0)/650;const mesh=BABYLON.MeshBuilder.CreateSphere('preview-system-'+i,{diameter:i===0?1.25:.35},scene);mesh.position=new BABYLON.Vector3(x,y,z);const mat=new BABYLON.StandardMaterial('preview-system-mat-'+i,scene);const c=sys.classification==='anomalous'?new BABYLON.Color3(1,.35,.22):sys.classification==='nebula-adjacent'?new BABYLON.Color3(.65,.4,1):sys.classification==='binary'?new BABYLON.Color3(.95,.72,.3):new BABYLON.Color3(.2,.75,.95);mat.emissiveColor=c;mesh.material=mat;meshes.push(mesh);});
   $('universePreviewFallback').style.display='none';$('universePreviewMapStatus').textContent=systems.length+' generated star systems · '+(universe?.generator_version?'generator v'+universe.generator_version:'preview');
  } catch(e){$('universePreviewFallback').style.display='block';$('universePreviewFallback').textContent='3D preview could not initialize. The form remains usable.';}}
 async function refresh(){displayControls();const seed=$('universeSeed').value.trim();if(!seed){$('previewFingerprint').textContent='Enter a seed';$('previewSystemCount').textContent='—';$('previewStatus').textContent='Enter a seed to generate an authoritative preview.';render({systems:[]});return;}const seq=++requestSeq;$('previewStatus').textContent='Generating universe preview…';try{const url=apiBase+'/api/universe-preview.php?seed='+encodeURIComponent(seed)+'&settings='+encodeURIComponent(JSON.stringify(settings()));const response=await fetch(url,{headers:{Accept:'application/json'}});const data=await response.json();if(seq!==requestSeq)return;if(!response.ok||data.ok===false)throw new Error(data.error?.message||'Preview request failed.');const u=data.universe;$('previewFingerprint').textContent=u.seed_fingerprint||'—';$('previewSystemCount').textContent=String(u.system_count??u.systems?.length??0);$('previewStatus').textContent='Preview reflects the current seed and settings. Saved universe generation will use this configuration.';render(u);}catch(e){$('previewStatus').textContent='Live preview unavailable: '+e.message;$('previewSystemCount').textContent='Unavailable';}}
 let timer;function schedule(){clearTimeout(timer);timer=setTimeout(refresh,180);}keys.forEach(k=>$(k).addEventListener('input',schedule));$('universeSeed').addEventListener('input',schedule);refresh();$('universeCreateForm').addEventListener('submit',e=>{if(!$('universeSeed').value.trim()){e.preventDefault();$('universeSeed').focus();}});
})();
</script></body></html>